Core Telehealth Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_telehealth_service, "Core Telehealth Service") {
    Component(Consultation_Manager, "Consultation Manager", "Go", "Manages video consultations and coordinates session flows.")
    Component(Prescription_Coordinator, "Prescription Coordinator", "Go", "Handles e-prescriptions and routes data to external pharmacy gateways.")
    Component(Consent_Verifier, "Consent Verifier", "Go", "Verifies patient consent against privacy regulations before treatment.")
    Component(Telemetry_Adaptation_Engine, "Telemetry & Adaptation Engine", "Go", "Monitors connection quality and adapts streaming for low-bandwidth environments.")
}

Rel(Consultation_Manager, Consent_Verifier, "Verifies patient consent via gRPC with mTLS", "gRPC / mTLS")
Rel(Consultation_Manager, Telemetry_Adaptation_Engine, "Tracks telemetry and network adaptation", "Internal")
Rel(Prescription_Coordinator, Consent_Verifier, "Validates consent before prescription generation", "gRPC / mTLS")

@enduml

AI Symptom Checker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("AI Symptom Checker Container", "AI Symptom Checker Container") {
    Component("API Router / Controller", "API Router / Controller", "Python / FastAPI", "Exposes endpoints and handles request routing for the symptom checker.")
    Component("Consent & Scope Validator", "Consent & Scope Validator", "Python / Middleware", "Middleware that validates patient consent and API scopes.")
    Component("Triage Engine", "Triage Engine", "Python/PyTorch or LangChain", "AI inference engine performing symptom-to-urgency assessments.")
    Component("Audit & Traceability Logger", "Audit & Traceability Logger", "Python / Asynchronous Logger", "Captures model inputs, versions, outputs, and clinician overrides.")
}

Rel("Consent & Scope Validator", "API Router / Controller", "Forwards validated requests", "Internal function call")
Rel("API Router / Controller", "Triage Engine", "Initiates urgency assessment", "In-memory function call")
Rel("Triage Engine", "Audit & Traceability Logger", "Captures model inputs, versions, and outputs", "Asynchronous event")

@enduml

Pharmacy Integration Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(pharmacy_integration_gateway, "Pharmacy Integration Gateway") {
    Component(Prescription_Orchestrator, "Prescription Orchestrator", "Go", "Orchestrates e-prescription workflows and manages internal routing using in-memory Go channels.")
    Component(Adapter_Engine, "Adapter Engine", "Go / Apache Camel", "Handles protocol mapping and submits e-prescriptions to external EU and US networks.")
    Component(Status_Audit_Publisher, "Status & Audit Publisher", "Go / Apache Camel", "Publishes event-driven status delivery acknowledgments to GCP Pub/Sub.")
    ComponentDb(Regional_State_Store, "Regional State Store", "Google Cloud Memorystore for Redis", "Reads and writes idempotency state with strict TTLs over TLS via internal VPC.")
}

Rel(Prescription_Orchestrator, Adapter_Engine, "Internal routing", "In-memory Go channels")
Rel(Prescription_Orchestrator, Regional_State_Store, "Read/Write idempotency state", "Redis Protocol over TLS via internal VPC")
Rel(Adapter_Engine, Status_Audit_Publisher, "Triggers status updates upon external prescription submission", "Internal event")
@enduml
